  //   [1] "Level 2", 43, 93, 4.87E+04, 5.454E+04, 1.397E+04, 40.56
  //   [2] "Roof", 51, 8, 5821, 6519, 1767, 62.04
buildingOnly = table.filter@1(table: named.table, expr: "Container == 'Building'");
