  //   [0] "Building", 36, 218, 1.157E+05, 1.296E+05, 3.72E+04, 42.68
buildingTotal = view.table@1(table: buildingOnly.table, title: "Building total", columns: "Container, Elements, Embodied A1-A3 (kgCO2e), Operational (kgCO2e/yr)");
  // Ok  table 1 rows x 4 cols  sha c321d55c77ff
  //   columns Container:Text, Elements:Integer, Embodied A1-A3 (kgCO2e):Number, Operational (kgCO2e/yr):Number
  //   [0] "Building", 218, 1.157E+05, 3.72E+04
storeysOnly = table.filter@1(table: named.table, expr: "Container != 'Building'");
