  //   [2] "Roof", 51, 8, 5821, 6519, 1767, 62.04
answer = chart.bar@1(table: storeysOnly.table, labelColumn: "Container", valueColumns: "Embodied A1-A3 (kgCO2e),Operational (kgCO2e/yr)", title: "Carbon per storey (synthetic)", sort: "desc");
